import { useEffect, useRef, useState, type ReactNode } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ClerkProvider, SignIn, SignUp, useAuth, useClerk, useUser } from '@clerk/react';
import { publishableKeyFromHost } from '@clerk/react/internal';
import { shadcn } from '@clerk/themes';
import { ArrowDownRight, ArrowLeft, ArrowRight, ArrowUpRight, BookOpen, Bookmark, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, Circle, Clock3, Code2, Compass, ExternalLink, FileCode2, Flame, FolderKanban, GraduationCap, LayoutDashboard, ListChecks, LogOut, Menu, Search, Settings2, Sparkles, Target, Trophy, X, Zap } from 'lucide-react';
import { Link, Route, Router as WouterRouter, Switch, useLocation } from 'wouter';
import { getGetLearningStateQueryKey, useGetLearningState, useSaveLearningState } from '@workspace/api-client-react';
import type { LearningState } from '@workspace/api-client-react';
import { lessons, projects, resources, stages } from '@/lib/curriculum';
import MarketingLanding from '@/pages/marketing-landing';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();
const basePath = import.meta.env.BASE_URL.replace(/\/$/, '');
const clerkPubKey = publishableKeyFromHost(window.location.hostname, import.meta.env.VITE_CLERK_PUBLISHABLE_KEY);
const clerkProxyUrl = import.meta.env.VITE_CLERK_PROXY_URL;
const defaultState: LearningState = { completedLessonIds:[], inProgressLessonIds:[], bookmarkedLessonIds:[], completedProjectIds:[], projectTaskChecks:{}, quizResults:[], dayGoalMinutes:30, activityMinutesByDate:{} };
const stateKey = 'devroadmap-learning-state-v1';
const localStateKey = (userId?:string) => `${stateKey}:${userId || 'guest'}`;
function readLocal(userId?:string): LearningState { try { const value = localStorage.getItem(localStateKey(userId)); return value ? { ...defaultState, ...JSON.parse(value) } : defaultState; } catch { return defaultState; } }
function stripBase(path: string) { return basePath && path.startsWith(basePath) ? path.slice(basePath.length) || '/' : path; }
const fmt = (n:number) => `${n}`.padStart(2,'0');
const today = new Date().toISOString().slice(0,10);
const stageOf = (lessonId:string) => lessons.find(l=>l.id===lessonId)?.stage.id ?? 1;

function Brand() {
  return <Link href="/" className="brand-lockup" aria-label="DevRoadmap home"><span className="brand-mark"><Code2 size={18}/></span><span className="brand-name">dev<span>roadmap</span><small>LEARN BY BUILDING</small></span></Link>;
}
const navItems = [
  { href:'/', label:'Overview', icon:LayoutDashboard },
  { href:'/roadmap', label:'Learning roadmap', icon:Compass },
  { href:'/resources', label:'Resource library', icon:BookOpen },
  { href:'/practice', label:'Practice lab', icon:Zap },
  { href:'/projects', label:'Projects', icon:FolderKanban },
  { href:'/dashboard', label:'My progress', icon:Target },
];

function App() {
  return <QueryClientProvider client={queryClient}><WouterRouter base={basePath}><ClerkProviderWithRoutes/></WouterRouter></QueryClientProvider>;
}
function ClerkProviderWithRoutes() {
  const [, setLocation] = useLocation();
  if (!clerkPubKey) {
    return <Switch>
      <Route path="/sign-in/*?" component={()=><AuthUnavailable type="sign in"/>}/>
      <Route path="/sign-up/*?" component={()=><AuthUnavailable type="create an account"/>}/>
      <Route path="/" component={MarketingLanding}/>
      <Route><LearningCore isSignedIn={false}/></Route>
    </Switch>;
  }
  const appearance = {
    theme:shadcn, cssLayerName:'clerk',
    options:{ logoPlacement:'inside' as const, logoLinkUrl:basePath||'/', logoImageUrl:`${window.location.origin}${basePath}/logo.svg` },
    variables:{ colorPrimary:'#318cf5', colorForeground:'#e8ecf6', colorMutedForeground:'#929db2', colorDanger:'#ed7272', colorBackground:'#111827', colorInput:'#0c1220', colorInputForeground:'#e8ecf6', colorNeutral:'#e8ecf6', fontFamily:'Manrope, sans-serif', borderRadius:'0.8rem' },
    elements:{ rootBox:'w-full flex justify-center', cardBox:'bg-[#111827] rounded-2xl w-[440px] max-w-full overflow-hidden border border-[#26314a]', card:'!shadow-none !border-0 !bg-transparent !rounded-none', footer:'!shadow-none !border-0 !bg-transparent !rounded-none', headerTitle:'text-[#eef3ff] font-bold', headerSubtitle:'text-[#9ca9bf]', socialButtonsBlockButtonText:'text-[#e7edf8]', formFieldLabel:'text-[#d8e1f2]', footerActionLink:'text-[#68aaff]', footerActionText:'text-[#9ca9bf]', dividerText:'text-[#8290aa]', identityPreviewEditButton:'text-[#6eafff]', formFieldSuccessText:'text-[#54d990]', alertText:'text-[#f2a1a1]', logoBox:'rounded-xl', logoImage:'rounded-xl', socialButtonsBlockButton:'border border-[#2a344b] !bg-[#151d2d]', formButtonPrimary:'!bg-[#2787f6] hover:!bg-[#4296fa]', formFieldInput:'!bg-[#0c1220] !border-[#2a344b] !text-[#e8ecf6]', footerAction:'border-t border-[#283249]', dividerLine:'bg-[#2a344b]', alert:'border-[#49333a]', otpCodeFieldInput:'!bg-[#0c1220] !border-[#2a344b]', formFieldRow:'text-[#d8e1f2]', main:'text-[#e8ecf6]' },
  };
  return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={appearance} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} localization={{signIn:{start:{title:'Welcome back',subtitle:'Pick up where your learning left off'}},signUp:{start:{title:'Start your journey',subtitle:'Build real skills, one step at a time'}}}} routerPush={(to)=>setLocation(stripBase(to))} routerReplace={(to)=>setLocation(stripBase(to),{replace:true})}>
    <Switch>
      <Route path="/" component={HomeRoute}/>
      <Route path="/sign-in/*?" component={SignInPage}/>
      <Route path="/sign-up/*?" component={SignUpPage}/>
      <Route><AuthenticatedLearningApp/></Route>
    </Switch>
  </ClerkProvider>;
}
function HomeRoute() {
  const {isSignedIn,isLoaded}=useAuth();
  if(!isLoaded)return <div className="home-loading"><span className="loading-mark"><Code2 size={19}/></span><span className="eyebrow">OPENING YOUR LEARNING SPACE</span></div>;
  return isSignedIn?<AuthenticatedLearningApp/>:<MarketingLanding/>;
}
function SignInPage(){ return <div className="auth-page"><div className="auth-intro"><Brand/><div className="auth-note"><span className="eyebrow">YOUR NEXT CHAPTER</span><h1>Small steps.<br/><em>Real momentum.</em></h1><p>A clear path from first line of code to your first role.</p></div><span className="auth-foot">DEVROADMAP · LEARN BY BUILDING</span></div><div className="auth-form"><Link href="/" className="auth-back"><ArrowLeft size={15}/> Back to learning</Link><SignIn routing="path" path={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`}/></div></div>; }
function SignUpPage(){ return <div className="auth-page"><div className="auth-intro"><Brand/><div className="auth-note"><span className="eyebrow">BUILD A CAREER, NOT JUST A COURSE</span><h1>Make learning<br/><em>feel possible.</em></h1><p>Keep your progress, projects, and next steps in one focused place.</p></div><span className="auth-foot">DEVROADMAP · LEARN BY BUILDING</span></div><div className="auth-form"><Link href="/" className="auth-back"><ArrowLeft size={15}/> Back to learning</Link><SignUp routing="path" path={`${basePath}/sign-up`} signInUrl={`${basePath}/sign-in`}/></div></div>; }
function AuthUnavailable({type}:{type:string}){ return <div className="auth-unavailable"><Brand/><div className="panel"><Sparkles size={24}/><h1>Keep your learning in sync.</h1><p>Account access is not configured yet. Your progress is saved on this device while authentication is being connected.</p><Link href="/" className="btn-primary button">Continue learning</Link><p className="tiny">To enable sign-in, configure the Clerk publishable key and proxy in the app environment.</p></div></div>; }

type AccountUser = { firstName:string|null; fullName:string|null; primaryEmailAddress?:{emailAddress:string}; update:(data:{firstName:string})=>Promise<unknown> };
function AuthenticatedLearningApp() {
  const { isSignedIn, userId } = useAuth();
  const { user } = useUser();
  const { signOut } = useClerk();
  return <LearningCore key={userId || 'guest'} isSignedIn={!!isSignedIn} userId={userId || undefined} user={user as AccountUser|null} signOut={()=>signOut({redirectUrl:basePath||'/'})}/>;
}
function LearningCore({isSignedIn,userId,user,signOut}:{isSignedIn:boolean;userId?:string;user?:AccountUser|null;signOut?:()=>void}) {
  const [state,setState] = useState<LearningState>(()=>readLocal(userId));
  const [mobileOpen,setMobileOpen] = useState(false);
  const [location] = useLocation();
  const syncedRef=useRef(false);
  const skipSaveRef=useRef(false);
  const remote = useGetLearningState({query:{enabled:!!isSignedIn, queryKey:[...getGetLearningStateQueryKey(),userId]}});
  const save = useSaveLearningState();
  useEffect(()=>{ if(remote.data&&!syncedRef.current){skipSaveRef.current=true;syncedRef.current=true;setState({...defaultState,...remote.data});} },[remote.data]);
  useEffect(()=>{ localStorage.setItem(localStateKey(userId),JSON.stringify(state)); },[state,userId]);
  useEffect(()=>{ if(skipSaveRef.current){skipSaveRef.current=false;return undefined;} if(isSignedIn && syncedRef.current && remote.data && !remote.isLoading){const timer=window.setTimeout(()=>save.mutate({data:state}),220);return ()=>window.clearTimeout(timer);} return undefined; },[state,isSignedIn]);
  const update=(fn:(prev:LearningState)=>LearningState)=>setState(prev=>fn(prev));
  const recordTime=(minutes=8)=>update(prev=>({...prev,activityMinutesByDate:{...prev.activityMinutesByDate,[today]:(prev.activityMinutesByDate[today]||0)+minutes}}));
  const markProgress=(id:string,completed:boolean)=>{
    update(prev=>({...prev,completedLessonIds:completed?[...new Set([...prev.completedLessonIds,id])]:prev.completedLessonIds.filter(x=>x!==id),inProgressLessonIds:completed?prev.inProgressLessonIds.filter(x=>x!==id):[...new Set([...prev.inProgressLessonIds,id])],activityMinutesByDate:{...prev.activityMinutesByDate,[today]:(prev.activityMinutesByDate[today]||0)+10}}));
  };
  const toggleBookmark=(id:string)=>update(prev=>({...prev,bookmarkedLessonIds:prev.bookmarkedLessonIds.includes(id)?prev.bookmarkedLessonIds.filter(x=>x!==id):[...prev.bookmarkedLessonIds,id]}));
  const completed=state.completedLessonIds.length;
  const pct=Math.round(completed/lessons.length*100);
  const active=lessons.find(l=>!state.completedLessonIds.includes(l.id));
  const username=user?.firstName || 'Learner';
  return <div className="app-shell">
    <aside className="sidebar"><Brand/><div className="side-section"><p className="side-label">WORKSPACE</p>{navItems.map(({href,label,icon:Icon})=><Link key={href} href={href} className={`nav-item ${location===href?'active':''}`} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ','-')}`}><Icon size={17}/><span>{label}</span></Link>)}</div><div className="side-bottom"><div className="goal-mini"><div className="goal-head"><Target size={14}/><span>Daily focus</span><strong>{state.activityMinutesByDate[today]||0}/{state.dayGoalMinutes}m</strong></div><div className="progress-track"><div className="progress-fill" style={{width:`${Math.min(100,(state.activityMinutesByDate[today]||0)/state.dayGoalMinutes*100)}%`}}/></div></div><Link href="/profile" className="profile-link"><span className="avatar">{(user?.firstName?.[0]||'L').toUpperCase()}</span><span className="side-label">{user?.fullName||'Your profile'}<small>{isSignedIn?'Learning account':'Local progress'}</small></span><Settings2 size={15}/></Link></div></aside>
    <div className="main-wrap"><header className="topbar"><button className="icon-button mobile-toggle" aria-label="Open navigation" onClick={()=>setMobileOpen(!mobileOpen)}><Menu size={18}/></button><div className="crumb"><span>LEARNING SPACE</span><i>/</i><strong>{navItems.find(n=>n.href===location)?.label || (location.startsWith('/lesson')?'Lesson':location.startsWith('/profile')?'Profile':'DevRoadmap')}</strong></div><div className="top-actions">{(remote.isError||save.isError)&&isSignedIn?<button className="sync-state sync-error" onClick={()=>remote.isError?remote.refetch():save.mutate({data:state})}><span className="sync-dot error-dot"/>Sync paused · retry</button>:<span className="sync-state"><span className={`sync-dot ${save.isPending?'saving':''}`}/>{isSignedIn?(remote.isLoading?'Syncing':save.isPending?'Saving':'Synced'):'Saved on this device'}</span>}{isSignedIn?<Link href="/profile" className="avatar avatar-top">{(user?.firstName?.[0]||'L').toUpperCase()}</Link>:<Link href="/sign-in" className="btn-quiet small-button">Sign in</Link>}</div></header>
      {mobileOpen&&<nav className="mobile-nav">{navItems.map(({href,label,icon:Icon})=><Link key={href} href={href} onClick={()=>setMobileOpen(false)} className={`nav-item ${location===href?'active':''}`}><Icon size={17}/><span>{label}</span></Link>)}<Link href="/profile" className="nav-item"><Settings2 size={17}/><span>Profile settings</span></Link></nav>}
      <main className="content page-enter">
        <Switch>
          <Route path="/" component={()=> <Overview username={username} state={state} pct={pct} active={active?.id} update={update} recordTime={recordTime}/>}/>
          <Route path="/roadmap" component={()=> <Roadmap state={state}/>}/>
          <Route path="/lesson/:lessonId">{params=><LessonPage lessonId={params.lessonId} state={state} markProgress={markProgress} toggleBookmark={toggleBookmark} recordTime={recordTime}/>}</Route>
          <Route path="/resources" component={()=> <Resources/>}/>
          <Route path="/practice" component={()=> <Practice state={state} update={update} recordTime={recordTime}/>}/>
          <Route path="/projects" component={()=> <Projects state={state} update={update} recordTime={recordTime}/>}/>
          <Route path="/dashboard" component={()=> <Dashboard state={state} pct={pct}/>}/>
          <Route path="/profile" component={()=> <Profile state={state} update={update} user={user} signOut={signOut}/>}/>
          <Route component={NotFound}/>
        </Switch>
      </main>
    </div>
  </div>;
}

function PageHeading({kicker,title,description,action}:{kicker:string;title:string;description:string;action?:ReactNode}) { return <div className="page-heading"><div><span className="eyebrow">{kicker}</span><h1>{title}</h1><p>{description}</p></div>{action}</div>; }
function Overview({username,state,pct,active,update,recordTime}:{username:string;state:LearningState;pct:number;active?:string;update:(fn:(p:LearningState)=>LearningState)=>void;recordTime:(m?:number)=>void}) {
 const lesson=lessons.find(l=>l.id===active)||lessons[0]; const goals=state.dayGoalMinutes; const todays=state.activityMinutesByDate[today]||0; const stageProgress=state.completedLessonIds.filter(id=>stageOf(id)===lesson.stage.id).length; const stageLessonCount=lesson.stage.lessons.length;
 const week=[6,5,4,3,2,1,0].map(offset=>{const d=new Date();d.setDate(d.getDate()-offset);const key=d.toISOString().slice(0,10);return {label:d.toLocaleDateString('en-US',{weekday:'short'}).slice(0,1),value:state.activityMinutesByDate[key]||0,key};});
 return <div className="overview-view"><div className="welcome-row"><div><span className="eyebrow">YOUR DEVELOPMENT JOURNEY</span><h1>Good to see you, {username}.</h1><p>One focused session is all it takes to move forward.</p></div><div className="welcome-date"><span>{new Intl.DateTimeFormat('en-US',{weekday:'long'}).format(new Date())}</span><strong>{new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric'}).format(new Date())}</strong></div></div>
 <div className="hero-learning panel"><div className="hero-copy"><div className="hero-tag"><span className="live-pulse"/>YOUR NEXT STEP <span>·</span> STAGE {fmt(lesson.stage.id)}</div><h2>{lesson.title}</h2><p>{lesson.stage.description}</p><div className="hero-meta"><span><BookOpen size={14}/>{lesson.stage.title}</span><span><Clock3 size={14}/>12 min</span></div><Link href={`/lesson/${lesson.id}`} className="btn-primary button" onClick={()=>{update(p=>({...p,inProgressLessonIds:[...new Set([...p.inProgressLessonIds,lesson.id])]}));recordTime(2)}}>Continue learning <ArrowRight size={16}/></Link></div><div className="learning-art" aria-hidden="true"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="orbit orbit-three"/><div className="orbit-core"><Code2 size={36}/></div><span className="orbit-node node-a"><FileCode2 size={16}/></span><span className="orbit-node node-b"><Check size={17}/></span><span className="orbit-node node-c">01</span><span className="art-label">BUILD / LEARN / REPEAT</span></div></div>
 <div className="metric-row"><div className="metric panel"><span className="metric-icon blue"><CheckCircle2 size={17}/></span><span className="eyebrow">LESSONS COMPLETE</span><strong>{state.completedLessonIds.length}<small> / {lessons.length}</small></strong><div className="progress-track"><div className="progress-fill" style={{width:`${pct}%`}}/></div></div><div className="metric panel"><span className="metric-icon green"><Flame size={17}/></span><span className="eyebrow">TODAY'S FOCUS</span><strong>{todays}<small> / {goals} min</small></strong><div className="progress-track"><div className="progress-fill green-fill" style={{width:`${Math.min(todays/goals*100,100)}%`}}/></div></div><div className="metric panel"><span className="metric-icon purple"><Trophy size={17}/></span><span className="eyebrow">PROJECTS SHIPPED</span><strong>{state.completedProjectIds.length}<small> / {projects.length}</small></strong><span className="metric-sub">Small builds add up.</span></div><div className="metric panel"><span className="metric-icon amber"><Zap size={17}/></span><span className="eyebrow">CURRENT STAGE</span><strong>{fmt(lesson.stage.id)}<small> / 15</small></strong><span className="metric-sub">{lesson.stage.title}</span></div></div>
 <div className="overview-grid"><section className="panel stage-progress"><div className="section-head"><div><span className="eyebrow">ROADMAP POSITION</span><h3>Your path, in progress</h3></div><Link href="/roadmap" className="text-link">View roadmap <ArrowUpRight size={14}/></Link></div><div className="stage-summary"><span className="stage-number">{fmt(lesson.stage.id)}</span><div className="stage-desc"><strong>{lesson.stage.title}</strong><span>{stageProgress} of {stageLessonCount} lessons complete</span></div><span className="stage-percent">{Math.round(stageProgress/stageLessonCount*100)}%</span></div><div className="path-track">{stages.slice(0,8).map(s=><span key={s.id} className={`path-node ${s.id<lesson.stage.id?'done':''} ${s.id===lesson.stage.id?'current':''}`} title={s.title}>{s.id<lesson.stage.id?<Check size={12}/>:fmt(s.id)}</span>)}<i>+7 stages</i></div><p className="path-caption">A steady route from fundamentals to job-ready work.</p></section>
 <section className="panel week-panel"><div className="section-head"><div><span className="eyebrow">YOUR RHYTHM</span><h3>Learning this week</h3></div><span className="week-total">{week.reduce((a,b)=>a+b.value,0)}<small> min</small></span></div><div className="week-chart">{week.map(day=><div className="week-day" key={day.key}><div className="bar-slot"><span className={day.key===today?'today-bar':''} style={{height:`${Math.max(7,Math.min(day.value/60*100,100))}%`}}/></div><small>{day.label}</small></div>)}</div><div className="chart-legend"><span className="legend-dot"/>Focus minutes</div></section></div>
 <div className="lower-grid"><section><div className="section-head"><div><span className="eyebrow">SAVED FOR LATER</span><h3>Bookmarked lessons</h3></div><Link href="/roadmap" className="text-link">Explore lessons <ArrowRight size={14}/></Link></div>{state.bookmarkedLessonIds.length? <div className="bookmark-list">{state.bookmarkedLessonIds.slice(0,3).map(id=>{const item=lessons.find(l=>l.id===id);return item?<Link key={id} href={`/lesson/${id}`} className="bookmark-row"><span className="bookmark-icon"><Bookmark size={15}/></span><span><strong>{item.title}</strong><small>Stage {fmt(item.stage.id)} · {item.stage.title}</small></span><ArrowRight size={15}/></Link>:null})}</div>:<div className="empty-inline"><Bookmark size={18}/><span>Save a lesson to keep your next reference close.</span></div>}</section><aside className="goal-card panel"><span className="eyebrow">DAILY COMMITMENT</span><h3>Make room for<br/><em>one more idea.</em></h3><p>Your goal is {goals} minutes a day. A short session builds a durable habit.</p><Link href="/profile" className="goal-link">Adjust your daily goal <ArrowRight size={14}/></Link></aside></div>
 </div>;
}

function Roadmap({state}:{state:LearningState}) {
 const [query,setQuery]=useState(''); const filtered=stages.map(stage=>({...stage,lessons:stage.lessons.filter(title=>`${title} ${stage.title}`.toLowerCase().includes(query.toLowerCase()))})).filter(s=>s.lessons.length);
 const done=state.completedLessonIds.length; return <><PageHeading kicker="THE CURRICULUM" title="A clear path forward." description={`${lessons.length} focused lessons across 15 stages. Learn in order, or follow your curiosity.`} action={<div className="roadmap-total"><strong>{done}</strong><span>of {lessons.length}<small> lessons complete</small></span></div>}/>
 <div className="roadmap-toolbar"><label className="search-box"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Find a lesson or stage" aria-label="Search lessons"/></label><span className="roadmap-status"><span className="status-dot"/>{Math.round(done/lessons.length*100)}% complete</span></div>
 <div className="roadmap-list">{filtered.map(stage=>{const stageDone=stage.lessons.filter(t=>{const l=lessons.find(x=>x.stage.id===stage.id&&x.title===t);return l&&state.completedLessonIds.includes(l.id)}).length;return <section key={stage.id} className={`stage-card panel ${stageDone===stage.lessons.length?'stage-finished':''}`}><div className="stage-rail"><span className={stageDone===stage.lessons.length?'rail-complete':''}>{stageDone===stage.lessons.length?<Check size={15}/>:fmt(stage.id)}</span><i/></div><div className="stage-main"><div className="stage-card-head"><div><span className="eyebrow">STAGE {fmt(stage.id)} <i>·</i> {stage.id<4?'FOUNDATIONS':stage.id<8?'FRONTEND':stage.id<12?'FULL STACK':'CAREER READY'}</span><h2>{stage.title}</h2><p>{stage.description}</p></div><span className="stage-count">{stageDone}/{stage.lessons.length}</span></div><div className="stage-bar"><div className="progress-track"><div className="progress-fill" style={{width:`${stageDone/stage.lessons.length*100}%`}}/></div></div><div className="lesson-grid">{stage.lessons.map(title=>{const item=lessons.find(l=>l.stage.id===stage.id&&l.title===title)!;const complete=state.completedLessonIds.includes(item.id);const progress=state.inProgressLessonIds.includes(item.id);return <Link href={`/lesson/${item.id}`} key={item.id} className={`lesson-row ${complete?'is-done':''}`}><span className="lesson-check">{complete?<Check size={12}/>:progress?<span/>:<Circle size={13}/>}</span><span>{title}</span>{state.bookmarkedLessonIds.includes(item.id)&&<Bookmark size={12} className="saved-mark"/>}<ArrowRight size={13} className="lesson-arrow"/></Link>})}</div></div></section>})}</div>
 </>;
}

function LessonPage({lessonId,state,markProgress,toggleBookmark,recordTime}:{lessonId:string;state:LearningState;markProgress:(id:string,complete:boolean)=>void;toggleBookmark:(id:string)=>void;recordTime:(n?:number)=>void}) {
 const idx=lessons.findIndex(l=>l.id===lessonId); const lesson=lessons[idx]; if(!lesson)return <NotFound/>; const completed=state.completedLessonIds.includes(lesson.id); const bookmarked=state.bookmarkedLessonIds.includes(lesson.id); const next=lessons[idx+1],prev=lessons[idx-1];
 const [answer,setAnswer]=useState<number|null>(null);
 const code=lesson.title.toLowerCase().includes('html')||lesson.stage.id===2?'<main>\\n  <h1>Make the web meaningful</h1>\\n  <p>Structure comes before style.</p>\\n</main>':lesson.title.toLowerCase().includes('css')||lesson.stage.id===3?'.learning-card {\\n  display: grid;\\n  gap: 1rem;\\n  padding: 1.5rem;\\n}':'const nextStep = (skills, curiosity) => {\\n  const practice = skills.map(skill => build(skill));\\n  return practice.length ? practice : curiosity;\\n};';
 const answerCorrect=answer===1;
 return <div className="lesson-view"><div className="lesson-topline"><Link href="/roadmap" className="back-link"><ArrowLeft size={14}/> Roadmap</Link><span>STAGE {fmt(lesson.stage.id)} <i>·</i> LESSON {fmt(lesson.index+1)}</span><button className={`bookmark-button ${bookmarked?'saved':''}`} onClick={()=>toggleBookmark(lesson.id)} aria-label={bookmarked?'Remove bookmark':'Bookmark lesson'} data-testid="button-bookmark-lesson"><Bookmark size={15}/>{bookmarked?'Saved':'Save lesson'}</button></div><div className="lesson-layout"><article className="lesson-content"><span className="eyebrow">{lesson.stage.title.toUpperCase()}</span><h1>{lesson.title}</h1><p className="lesson-intro">{introFor(lesson.title)}</p><div className="lesson-meta"><span><Clock3 size={14}/>12 min read</span><span><GraduationCap size={15}/>{lesson.stage.id<=3?'Beginner':lesson.stage.id<=9?'Intermediate':'Advanced'}</span><span><Circle size={8} className="blue-text"/>Learning objective</span></div><div className="article-rule"/>
 <section className="article-section"><h2>Start with the idea</h2><p>{explainFor(lesson.title)} The goal is not to memorize every detail at once. Build a small mental model, try it in code, then return to the concept as you encounter it in real work.</p><div className="concept-callout"><span className="callout-icon"><Sparkles size={16}/></span><p><strong>Keep in mind</strong><br/>A useful developer habit is to ask what problem a tool solves before learning its syntax.</p></div></section>
 <section className="article-section"><h2>See it in context</h2><p>Here is a compact example you can adapt. Notice how each part has one clear job.</p><div className="code-header"><span><i/> EXAMPLE.{lesson.stage.id===2?'html':lesson.stage.id===3?'css':'js'}</span><button onClick={()=>navigator.clipboard?.writeText(code)} data-testid="button-copy-example">Copy example</button></div><pre className="code-panel"><code>{code}</code></pre></section>
 <section className="article-section"><h2>Try it yourself</h2><p>Work through the steps in your own editor. Keep the result small enough to finish in one sitting.</p><ol className="step-list"><li><span>01</span><p>Create a fresh file or sandbox and write down what you expect to happen.</p></li><li><span>02</span><p>Change one thing at a time, then compare the output with your expectation.</p></li><li><span>03</span><p>Explain the result in your own words before moving on.</p></li></ol></section>
 <section className="article-section"><h2>Common mistakes to avoid</h2><div className="mistake-row"><span>01</span><p>Copying an example without changing it. Small experiments make the idea stick.</p></div><div className="mistake-row"><span>02</span><p>Skipping the browser or terminal feedback. Read errors as clues, not failures.</p></div><div className="mistake-row"><span>03</span><p>Trying to learn several new concepts in one pass. Focus on the next useful step.</p></div></section>
 <section className="quiz-card"><div className="quiz-heading"><span className="quiz-icon"><Zap size={16}/></span><div><span className="eyebrow">QUICK KNOWLEDGE CHECK</span><h2>What makes a concept stick?</h2></div></div><div className="quiz-options">{['Read the same definition repeatedly','Apply it in a small experiment and explain the result','Skip practice and move to a harder topic'].map((option,i)=><button key={option} onClick={()=>setAnswer(i)} className={`quiz-option ${answer===i?'selected':''} ${answer!==null&&i===1?'correct':''} ${answer===i&&i!==1?'incorrect':''}`}><span>{String.fromCharCode(65+i)}</span>{option}{answer!==null&&i===1&&<Check size={15}/>}</button>)}</div>{answer!==null&&<p className={`quiz-feedback ${answerCorrect?'good':'bad'}`}>{answerCorrect?'Exactly. Active practice and explanation reveal what you understand.':'Not quite. Retrieval and application create stronger understanding than rereading.'}</p>}</section>
 <div className="lesson-complete panel"><div><span className="eyebrow">MAKE IT COUNT</span><h3>{completed?'You have this one in the bank.':'Ready to mark this lesson done?'}</h3><p>Your progress stays with you as you move through the roadmap.</p></div><button className={completed?'btn-quiet button':'btn-primary button'} onClick={()=>{markProgress(lesson.id,!completed);recordTime(10)}} data-testid="button-toggle-complete">{completed?<><CheckCircle2 size={16}/> Completed</>:<><Check size={16}/> Mark complete</>}</button></div>
 <div className="lesson-pagination">{prev?<Link href={`/lesson/${prev.id}`} className="pagination-link"><ChevronLeft size={17}/><span><small>PREVIOUS</small><strong>{prev.title}</strong></span></Link>:<span/>}{next?<Link href={`/lesson/${next.id}`} className="pagination-link next"><span><small>NEXT LESSON</small><strong>{next.title}</strong></span><ChevronRight size={17}/></Link>:<Link href="/projects" className="pagination-link next"><span><small>UP NEXT</small><strong>Build a project</strong></span><ChevronRight size={17}/></Link>}</div>
 </article><aside className="lesson-aside"><div className="aside-card panel"><span className="eyebrow">IN THIS STAGE</span><div className="aside-stage-title">{lesson.stage.title}</div><div className="aside-stage-progress"><div className="progress-track"><div className="progress-fill" style={{width:`${state.completedLessonIds.filter(id=>stageOf(id)===lesson.stage.id).length/lesson.stage.lessons.length*100}%`}}/></div><span>{state.completedLessonIds.filter(id=>stageOf(id)===lesson.stage.id).length}/{lesson.stage.lessons.length}</span></div>{lesson.stage.lessons.map((name,i)=>{const l=lessons.find(x=>x.stage.id===lesson.stage.id&&x.title===name)!;return <Link key={l.id} href={`/lesson/${l.id}`} className={`aside-lesson ${l.id===lesson.id?'current':''} ${state.completedLessonIds.includes(l.id)?'done':''}`}><span>{state.completedLessonIds.includes(l.id)?<Check size={11}/>:fmt(i+1)}</span>{name}</Link>})}</div><div className="resource-nudge panel"><span className="eyebrow">GOOD NEXT READ</span><h4>Learn from the source.</h4><p>Official docs help you connect this topic to real-world use.</p><Link href="/resources" className="text-link">Browse resources <ArrowUpRight size={13}/></Link></div></aside></div></div>;
}
function introFor(t:string){return `${t} is one of the building blocks that helps turn a beginner's curiosity into working software.`}
function explainFor(t:string){return `When you work with ${t.toLowerCase()}, focus first on its role in the larger web development workflow. Understand the input, the outcome, and the decisions you can control. That practical framing makes details easier to remember.`}

function Resources() {
 const [search,setSearch]=useState(''); const [category,setCategory]=useState('All categories'); const [level,setLevel]=useState('All levels'); const cats=['All categories',...Array.from(new Set(resources.map(r=>r.category)))];
 const items=resources.filter(r=>(r.title+' '+r.description+' '+r.category).toLowerCase().includes(search.toLowerCase())&&(category==='All categories'||r.category===category)&&(level==='All levels'||r.level===level));
 return <><PageHeading kicker="THE FIELD GUIDE" title="Good tools. Better sources." description="A curated shelf of trusted documentation, courses, and places to practice."/><section className="resource-controls panel"><label className="search-box resource-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search documentation, courses, tools..." aria-label="Search resources"/></label><label className="select-label"><span>CATEGORY</span><select className="control" value={category} onChange={e=>setCategory(e.target.value)}>{cats.map(c=><option key={c}>{c}</option>)}</select></label><label className="select-label"><span>LEVEL</span><select className="control" value={level} onChange={e=>setLevel(e.target.value)}>{['All levels','Beginner','Intermediate','Advanced'].map(x=><option key={x}>{x}</option>)}</select></label></section><div className="resource-count"><span>{items.length} resources</span><span>Reviewed for a useful next step</span></div>{items.length?<div className="resource-grid">{items.map((item,i)=><article className="resource-card panel" key={item.title}><div className={`resource-symbol symbol-${i%4}`}><BookOpen size={19}/></div><div className="resource-card-tags"><span>{item.category}</span><i>·</i><span>{item.level}</span></div><h3>{item.title}</h3><p>{item.description}</p><a className="resource-link" href={item.url} target="_blank" rel="noreferrer">{new URL(item.url).hostname.replace('www.','')} <ExternalLink size={13}/></a></article>)}</div>:<div className="empty-state panel"><Search size={23}/><h3>No matches just yet.</h3><p>Try a different keyword, category, or difficulty level.</p><button className="btn-quiet button" onClick={()=>{setSearch('');setCategory('All categories');setLevel('All levels')}}>Clear filters</button></div>}</>;
}

const quizBank=[
 {id:'html-semantics',title:'HTML & structure',level:'Beginner',questions:[{q:'Which element best describes the primary content of a page?',a:['<div>','<main>','<span>'],correct:1,why:'The main element identifies the dominant content of the document.'},{q:'What should an image use to convey its meaning to screen readers?',a:['A title only','A descriptive alt attribute','A larger file size'],correct:1,why:'Alt text supplies a text equivalent for meaningful images.'},{q:'Which heading is normally the top-level page heading?',a:['<h1>','<h4>','<header>'],correct:0,why:'An h1 represents the page’s highest-level heading.'}]},
 {id:'css-layout',title:'CSS layout essentials',level:'Beginner',questions:[{q:'Which layout system is designed for one-dimensional alignment?',a:['Flexbox','Grid','Float'],correct:0,why:'Flexbox excels at arranging items along a row or column.'},{q:'What does box-sizing: border-box change?',a:['Includes padding and border in the declared size','Removes the content box','Makes every element a grid'],correct:0,why:'Border-box keeps declared width inclusive of padding and borders.'},{q:'Which unit is relative to the root font size?',a:['px','rem','vh'],correct:1,why:'A rem is based on the computed font size of the root element.'}]},
 {id:'javascript-basics',title:'JavaScript foundations',level:'Beginner',questions:[{q:'Which array method returns a new array of transformed values?',a:['forEach','map','push'],correct:1,why:'map creates a new array by applying a function to each element.'},{q:'What does await do inside an async function?',a:['Pauses that function until a promise settles','Stops the browser','Turns a value into a callback'],correct:0,why:'await pauses the async function and unwraps a settled promise.'},{q:'Which comparison checks value and type?',a:['=','==','==='],correct:2,why:'Strict equality checks both type and value.'}]},
 {id:'react-patterns',title:'React component thinking',level:'Intermediate',questions:[{q:'What is a prop used for?',a:['Passing data into a component','Persisting data to a database','Styling only'],correct:0,why:'Props are inputs passed from a parent component.'},{q:'When should state be updated?',a:['Directly mutate it','Use the state setter','Only in a render function'],correct:1,why:'The setter schedules a render with the next state value.'},{q:'What should a list item key identify?',a:['A stable item identity','The color of the item','The parent component'],correct:0,why:'Stable keys help React track list items across renders.'}]},
 {id:'web-architecture',title:'Web architecture',level:'Advanced',questions:[{q:'What does a cache primarily help reduce?',a:['Repeated expensive work or network requests','HTML semantics','All security risks'],correct:0,why:'Caches can avoid recomputing or refetching data that remains valid.'},{q:'Why validate input on the server?',a:['Client-side checks can be bypassed','It makes CSS load faster','Browsers require it'],correct:0,why:'The server is the trust boundary and must validate untrusted input.'},{q:'What does SSR mean?',a:['Server-side rendering','Static style rules','Secure session routing'],correct:0,why:'Server-side rendering produces HTML on the server for a request.'}]},
];
function Practice({state,update,recordTime}:{state:LearningState;update:(fn:(p:LearningState)=>LearningState)=>void;recordTime:(m?:number)=>void}) {
 const [quizId,setQuizId]=useState(quizBank[0].id); const quiz=quizBank.find(q=>q.id===quizId)!; const [qIndex,setQIndex]=useState(0);const [choice,setChoice]=useState<number|null>(null);const [answers,setAnswers]=useState<number[]>([]);const [done,setDone]=useState(false);const question=quiz.questions[qIndex];
 function choose(i:number){if(choice!==null)return;setChoice(i);setAnswers(a=>[...a,i])}
 function advance(){if(qIndex<quiz.questions.length-1){setQIndex(q=>q+1);setChoice(null)}else{const score=answers.filter((a,i)=>a===quiz.questions[i].correct).length;update(p=>({...p,quizResults:[{quizId:quiz.id,score,total:quiz.questions.length,completedAt:new Date().toISOString()},...p.quizResults]}));recordTime(8);setDone(true)}}
 function restart(id=quizId){setQuizId(id);setQIndex(0);setChoice(null);setAnswers([]);setDone(false)}
 const latest=state.quizResults.slice(0,4);
 return <><PageHeading kicker="PRACTICE LAB" title="Know it by doing it." description="Short, focused checks. Instant feedback. A little more confidence each time."/><div className="practice-layout"><section className="practice-main panel"><div className="practice-top"><div><span className="eyebrow">{done?'SESSION COMPLETE':'QUICK CHECK'}</span><h2>{done?'Nice work. Keep the signal.':quiz.title}</h2></div><label className="quiz-picker"><span className="sr-only">Select quiz</span><select className="control" value={quizId} onChange={e=>restart(e.target.value)}>{quizBank.map(q=><option value={q.id} key={q.id}>{q.title}</option>)}</select></label></div>{done?<div className="quiz-result"><div className="result-ring"><strong>{answers.filter((a,i)=>a===quiz.questions[i].correct).length}<small>/{quiz.questions.length}</small></strong></div><h3>{answers.filter((a,i)=>a===quiz.questions[i].correct).length===quiz.questions.length?'Clean sweep.':'Good practice is progress.'}</h3><p>{answers.filter((a,i)=>a===quiz.questions[i].correct).length} correct answers. Review the explanations and give it another go when you’re ready.</p><button onClick={()=>restart()} className="btn-primary button">Try again <ArrowRight size={15}/></button></div>:<><div className="question-progress"><span>QUESTION {fmt(qIndex+1)} <i>OF {fmt(quiz.questions.length)}</i></span><div className="progress-track"><div className="progress-fill" style={{width:`${(qIndex+1)/quiz.questions.length*100}%`}}/></div></div><h3 className="question-text">{question.q}</h3><div className="answer-list">{question.a.map((option,i)=><button key={option} onClick={()=>choose(i)} className={`answer-option ${choice===i?'chosen':''} ${choice!==null&&i===question.correct?'answer-right':''} ${choice===i&&i!==question.correct?'answer-wrong':''}`}><span>{String.fromCharCode(65+i)}</span>{option}{choice!==null&&i===question.correct&&<Check size={16}/>}</button>)}</div>{choice!==null&&<div className={`answer-explanation ${choice===question.correct?'explain-correct':'explain-wrong'}`}><strong>{choice===question.correct?'That’s right.':'Not quite yet.'}</strong><p>{question.why}</p></div>}<div className="question-footer"><span><Zap size={14}/> {quiz.level} · no timer</span><button disabled={choice===null} onClick={advance} className="btn-primary button">{qIndex===quiz.questions.length-1?'Finish quiz':'Next question'} <ArrowRight size={15}/></button></div></>}</section><aside className="practice-side"><div className="panel practice-history"><div className="section-head"><div><span className="eyebrow">YOUR RECENT SCORES</span><h3>Practice history</h3></div><Trophy size={17}/></div>{latest.length?latest.map((r,i)=><div className="history-row" key={`${r.completedAt}-${i}`}><span className="history-score">{r.score}<small>/{r.total}</small></span><span className="history-name">{quizBank.find(q=>q.id===r.quizId)?.title||r.quizId}<small>{new Date(r.completedAt).toLocaleDateString()}</small></span><span className="history-percent">{Math.round(r.score/r.total*100)}%</span></div>):<div className="empty-compact"><span className="empty-ring"><ListChecks size={17}/></span><strong>Your first score is waiting.</strong><p>Complete a quick check to start a useful record of what you know.</p></div>}</div><div className="tip-card"><span className="eyebrow">A GOOD STUDY LOOP</span><p>Recall first. Check the answer. Explain why. Then build something with it.</p></div></aside></div></>;
}

function Projects({state,update,recordTime}:{state:LearningState;update:(fn:(p:LearningState)=>LearningState)=>void;recordTime:(m?:number)=>void}) {
 const [level,setLevel]=useState('All levels');const [open,setOpen]=useState<string|null>(null);const filtered=projects.filter(p=>level==='All levels'||p.level===level);
 function checkTask(projectId:string,task:string){update(p=>{const checks=p.projectTaskChecks[projectId]||[];const next=checks.includes(task)?checks.filter(x=>x!==task):[...checks,task];const all=projects.find(x=>x.id===projectId)?.tasks.length===next.length;return {...p,projectTaskChecks:{...p.projectTaskChecks,[projectId]:next},completedProjectIds:all?[...new Set([...p.completedProjectIds,projectId])]:p.completedProjectIds.filter(x=>x!==projectId)}});recordTime(3)}
 return <><PageHeading kicker="THE BUILD STUDIO" title="Make something real." description="Choose a brief, make it yours, and keep a visible trail of the work." action={<label className="project-filter"><span>LEVEL</span><select className="control" value={level} onChange={e=>setLevel(e.target.value)}>{['All levels','Beginner','Intermediate','Advanced'].map(x=><option key={x}>{x}</option>)}</select></label>}/><div className="project-intro panel"><div className="project-intro-icon"><Code2 size={21}/></div><div><span className="eyebrow">PROJECTS ARE PROOF OF WORK</span><h3>Finished is more valuable than perfect.</h3><p>Each brief has a sequence of practical tasks. Check them off as you build; finishing every step records the project as complete.</p></div><span className="project-counter"><strong>{state.completedProjectIds.length}</strong><small>shipped</small></span></div><div className="project-list">{filtered.map((project,i)=>{const checks=state.projectTaskChecks[project.id]||[];const isDone=state.completedProjectIds.includes(project.id);const expanded=open===project.id;return <article className={`project-card panel ${isDone?'project-done':''}`} key={project.id}><div className="project-index">{String(i+1).padStart(2,'0')}</div><div className="project-info"><div className="project-tags"><span className={`level-tag ${project.level.toLowerCase()}`}>{project.level}</span><span>{project.stage}</span>{isDone&&<span className="completed-tag"><CheckCircle2 size={12}/> COMPLETE</span>}</div><button className="project-title-button" onClick={()=>setOpen(expanded?null:project.id)} aria-expanded={expanded}><h3>{project.title}</h3><ChevronDown size={17}/></button><p>{project.description}</p><div className="project-progress-row"><div className="progress-track"><div className="progress-fill" style={{width:`${checks.length/project.tasks.length*100}%`}}/></div><span>{checks.length}/{project.tasks.length} tasks</span></div>{expanded&&<div className="project-tasks">{project.tasks.map((task,j)=><label className={`task-check ${checks.includes(task)?'checked':''}`} key={task}><input type="checkbox" checked={checks.includes(task)} onChange={()=>checkTask(project.id,task)}/><span className="custom-check">{checks.includes(task)&&<Check size={12}/>}</span><span><small>STEP {fmt(j+1)}</small>{task}</span></label>)}<div className="project-result"><span className="eyebrow">EXPECTED RESULT</span><p>A complete {project.title.toLowerCase()} that you can share, explain, and improve.</p></div></div>}</div><button className="project-open" onClick={()=>setOpen(expanded?null:project.id)} aria-label={`${expanded?'Collapse':'Expand'} ${project.title}`}><ArrowDownRight size={17}/></button></article>})}</div></>;
}

function Dashboard({state,pct}:{state:LearningState;pct:number}) {
 const inProgress=lessons.filter(l=>state.inProgressLessonIds.includes(l.id)&&!state.completedLessonIds.includes(l.id));const latest=state.completedLessonIds.map(id=>lessons.find(l=>l.id===id)).filter(Boolean).slice(-4).reverse();const totalMinutes=Object.values(state.activityMinutesByDate).reduce((a,b)=>a+b,0);const activeStage=lessons.find(l=>!state.completedLessonIds.includes(l.id))?.stage.id||15;const weekly=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=d.toISOString().slice(0,10);return {date:key,label:d.toLocaleDateString('en-US',{weekday:'short'}),min:state.activityMinutesByDate[key]||0};});
 const achievements=[{title:'First commit',desc:'Complete your first lesson',earned:state.completedLessonIds.length>0,icon:CheckCircle2},{title:'Curious builder',desc:'Finish a project',earned:state.completedProjectIds.length>0,icon:Code2},{title:'Daily rhythm',desc:'Reach your daily goal',earned:(state.activityMinutesByDate[today]||0)>=state.dayGoalMinutes,icon:Flame},{title:'Roadmap explorer',desc:'Complete 10 lessons',earned:state.completedLessonIds.length>=10,icon:Compass}];
 return <><PageHeading kicker="YOUR LEARNING SIGNAL" title="Progress, not perfection." description="A useful snapshot of what you have learned and where to put your energy next."/><div className="dashboard-hero panel"><div className="dashboard-score"><span className="eyebrow">ROADMAP COMPLETION</span><div className="score-line"><strong>{pct}<small>%</small></strong><div><span>{state.completedLessonIds.length} lessons complete</span><small>Stage {fmt(activeStage)} is your current focus</small></div></div><div className="progress-track score-track"><div className="progress-fill" style={{width:`${pct}%`}}/></div><p>Small, consistent progress builds a portfolio of real skills.</p></div><div className="score-graphic"><div className="ring-progress" style={{background:`conic-gradient(#328df4 ${pct*3.6}deg,#273149 ${pct*3.6}deg)`}}><div><strong>{fmt(activeStage)}</strong><small>STAGE</small></div></div></div><div className="dashboard-stats"><div><span className="eyebrow">LEARNING TIME</span><strong>{Math.floor(totalMinutes/60)}<small>h</small> {totalMinutes%60}<small>m</small></strong></div><div><span className="eyebrow">IN PROGRESS</span><strong>{inProgress.length}</strong></div><div><span className="eyebrow">PROJECTS DONE</span><strong>{state.completedProjectIds.length}</strong></div></div></div><div className="dashboard-grid"><section className="panel activity-panel"><div className="section-head"><div><span className="eyebrow">WEEKLY ACTIVITY</span><h3>Showing up is the skill.</h3></div><span className="activity-total">{weekly.reduce((a,d)=>a+d.min,0)}<small> min</small></span></div><div className="activity-chart">{weekly.map(d=><div className="activity-day" key={d.date}><span className="activity-value">{d.min>0?`${d.min}m`:''}</span><div className="activity-bar"><span style={{height:`${Math.max(8,Math.min(d.min/state.dayGoalMinutes*100,100))}%`}}/></div><small>{d.label}</small></div>)}</div><div className="activity-foot"><span><i/> Minutes logged on this device</span><Link href="/profile" className="text-link">Daily goal: {state.dayGoalMinutes}m <ArrowRight size={13}/></Link></div></section><section className="panel achievement-panel"><div className="section-head"><div><span className="eyebrow">MILESTONES</span><h3>Proof you’re moving.</h3></div><Trophy size={17}/></div><div className="achievement-list">{achievements.map(({title,desc,earned,icon:Icon})=><div className={`achievement ${earned?'earned':''}`} key={title}><span><Icon size={16}/></span><div><strong>{title}</strong><small>{desc}</small></div>{earned?<CheckCircle2 size={15}/>:<Circle size={15}/>}</div>)}</div></section></div><div className="dashboard-grid lower-dashboard"><section><div className="section-head"><div><span className="eyebrow">PICK UP AGAIN</span><h3>In progress</h3></div><Link href="/roadmap" className="text-link">Roadmap <ArrowRight size={13}/></Link></div>{inProgress.length?inProgress.slice(0,3).map(l=><Link href={`/lesson/${l.id}`} key={l.id} className="progress-lesson"><span className="lesson-icon"><BookOpen size={16}/></span><span><strong>{l.title}</strong><small>Stage {fmt(l.stage.id)} · {l.stage.title}</small></span><ArrowRight size={15}/></Link>):<div className="empty-inline"><BookOpen size={18}/><span>Start a lesson and it will appear here.</span></div>}</section><section><div className="section-head"><div><span className="eyebrow">RECENTLY COMPLETED</span><h3>Your latest wins</h3></div></div>{latest.length?latest.map(l=><Link href={`/lesson/${l!.id}`} key={l!.id} className="recent-lesson"><CheckCircle2 size={15}/><span>{l!.title}</span><small>STAGE {fmt(l!.stage.id)}</small></Link>):<div className="empty-inline"><CheckCircle2 size={18}/><span>Your completed lessons will show here.</span></div>}</section></div></>;
}

function Profile({state,update,user,signOut}:{state:LearningState;update:(fn:(p:LearningState)=>LearningState)=>void;user?:AccountUser|null;signOut?:()=>void}) {
 const [goal,setGoal]=useState(String(state.dayGoalMinutes));const [displayName,setDisplayName]=useState(user?.firstName||'Learner');const [saved,setSaved]=useState(false);const [busy,setBusy]=useState(false);
 async function saveProfile(){const n=Math.max(5,Math.min(240,Number(goal)||30));update(p=>({...p,dayGoalMinutes:n}));setGoal(String(n));if(user){setBusy(true);try{await user.update({firstName:displayName});setSaved(true);window.setTimeout(()=>setSaved(false),2200)}catch{setSaved(false)}finally{setBusy(false)}}else{setSaved(true);window.setTimeout(()=>setSaved(false),2200)}}
 return <><PageHeading kicker="ACCOUNT & PREFERENCES" title="Set up your learning space." description="A few personal settings make your roadmap feel like yours."/><div className="profile-layout"><section className="panel profile-section"><div className="profile-section-head"><span className="profile-large-avatar">{(user?.firstName?.[0]||'L').toUpperCase()}</span><div><span className="eyebrow">YOUR ACCOUNT</span><h2>{user?.fullName||'Local learner'}</h2><p>{user?.primaryEmailAddress?.emailAddress||'Progress is stored on this device'}</p></div></div><div className="form-line"><label htmlFor="display-name">Display name</label><input className="control" id="display-name" value={displayName} onChange={e=>setDisplayName(e.target.value)}/><small>{user?'Your name is managed securely by your account provider.':'This name stays in your local profile.'}</small></div><div className="form-line"><label htmlFor="daily-goal">Daily learning goal</label><div className="goal-input"><input id="daily-goal" className="control" type="number" min="5" max="240" value={goal} onChange={e=>setGoal(e.target.value)}/><span>minutes a day</span></div><small>Choose a goal between 5 and 240 minutes. You can adjust it whenever life changes.</small></div><button onClick={saveProfile} className="btn-primary button" disabled={busy}>{saved?<><Check size={15}/> Preferences saved</>:busy?'Saving…':'Save preferences'}</button></section><aside className="profile-aside"><div className="panel privacy-card"><span className="privacy-icon"><Settings2 size={17}/></span><span className="eyebrow">YOUR DATA</span><h3>Learning belongs to you.</h3><p>When signed in, your progress syncs using the platform learning-state API. Otherwise it remains in this browser.</p><div className="sync-indicator"><span className={user?'sync-dot':'sync-dot local-dot'}/>{user?'Account connected':'Local-only mode'}</div></div>{user?<button className="btn-quiet button logout-button" onClick={signOut}><LogOut size={15}/> Sign out</button>:<Link href="/sign-in" className="btn-quiet button logout-button">Sign in to sync <ArrowRight size={15}/></Link>}</aside></div></>;
}

export default App;
